// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with exactly 10 ether
        vm.deal(address(c), 10 ether);
        // Set up caller and warp to a block where block.number % 15 == 0
        // Use block 15 for simplicity
        vm.roll(15);
        // Warp to a future timestamp so the timestamp requirement passes
        vm.warp(100);
        vm.deal(address(this), 10 ether);
        // Call fallback with 10 ether
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");
        // Now the buggy version transfers address(this).balance + 1,
        // which would revert if balance is not enough.
        // However the contract balance after receiving 10 ether is 20 ether,
        // so transfer tries to send 21 ether -> revert.
        // We assert that the call succeeded (reference) or we catch revert.
        // Actually the fallback itself sends; we need to ensure the fallback runs.
        // Since we already called, the transfer already happened.
        // Observe: on reference, contract balance ends 10 ether (transferred 10 back)
        // On buggy, the transfer reverts because balance < 21 ether.
        // But our call already succeeded? Actually require(msg.value == 10) passes,
        // then time passes, then transfer inside fallback reverts.
        // The whole fallback reverts so our (bool ok, ) will be false.
        // So we assert true on reference (call succeeded) and false on buggy.
        assertTrue(ok);
    }
}

