        vm.warp(1002);
        vm.roll(2);
        vm.deal(address(0x2), 10 ether);
        vm.prank(address(0x2));
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second fallback reverted");

        // Now check contract balance:
        // Reference version: initial 1 + 10 + 10 = 21, no transfer because block.number%15!=0
        // Buggy version: initial 1 + 10 + 10 = 21, but then two transfers failed? Actually the bug is in the if block: when block.number%15 == 0, it transfers balance+1.
        // In this scenario, block.number never %15 == 0, so no transfers happen -> both have 21.
        // But wait: we need divergence. Let's make block.number%15 == 0 on the second call.
        // Actually, let's redo: let block.number%15 == 0 on second call.
        // We'll restart.
    }
}

