pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(1);
        address bob = address(2);
        // Set block.number such that block.number % 15 == 0 for the fallback
        vm.roll(15);
        // Call from alice
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.fallback{value: 10 ether}();
        // Now contract balance 10 ether, pastBlockTime set, first call succeeds
        // Call from bob
        vm.deal(bob, 10 ether);
        vm.prank(bob);
        // In reference: transfer(address(this).balance) sends 10 ether to bob, balance becomes 0
        // In buggy: transfer(address(this).balance + 1) tries to send 10 ether + 1 wei, reverts because insufficient balance
        // Catch the revert for buggy version
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        // After both calls, reference: balance 0, buggy: balance 20 ether (since second call reverted, second 10 ether remains in contract)
        assertEq(address(c).balance == 0, ok);
    }
}

