pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a scenario at block 15 with a specific timestamp
        vm.warp(1000);
        vm.roll(15);

        // Fund an account with enough ether
        address alice = address(0xA11CE);
        vm.deal(alice, 10 ether);

        // First call: succeeds in both versions
        vm.prank(alice);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1); // First call always succeeds

        // Now a second call with the SAME timestamp (still 1000) should succeed in buggy version
        // but fail in reference because reference requires strictly greater timestamp
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // Reference: requires block.timestamp > pastBlockTime => 1000 > 1001 => false => revert => ok2 = false
        // Bug: requires block.timestamp >= pastBlockTime => 1000 >= 1001 => false => revert => ok2 = false
        // Actually both revert because pastBlockTime = 1000+1 = 1001, and 1000 >= 1001 is false
        // I need a different scenario: Let the bug allow equal timestamps
        // Reset and do two calls with same timestamp: block.timestamp = 1000, after first call pastBlockTime = 1001
        // Second call at same timestamp: reference reverts (1000 > 1001 false), bug also reverts (1000 >= 1001 false)
        // Both revert. Need bug to succeed where reference fails.
        // Scenario: call at time 1000, then call at time 1000 (same timestamp) - bug requires >=, so 1000 >= 1000 would pass if pastBlockTime was 1000, but it was set to 1001 (1000+1)
        // Actually the +1 makes both fail. So I need to skip the +1? No, that's in both.
        // Let me rethink: The bug only changes > to >=.  
        // For the bug to pass where reference fails, we need block.timestamp == pastBlockTime exactly.
        // But pastBlockTime is always set to block.timestamp + 1, so equality never holds.
        // So the bug doesn't actually change behavior! Let me re-examine the code.
        // Reference: block.timestamp > pastBlockTime
        // Bug: block.timestamp >= pastBlockTime
        // pastBlockTime is always block.timestamp + 1 from previous call
        // So condition for next call: block.timestamp > (previous block.timestamp + 1) reference, or block.timestamp >= (previous block.timestamp + 1) bug
        // Both require block.timestamp > previous block.timestamp, so no difference.
        // The bug has no observable effect! But the problem says it breaks a property...
        // Perhaps the original contract had pastBlockTime = block.timestamp (without +1) and the modified has +1? No, both have +1.
        // Actually wait: maybe the intended bug is that the >= allows multiple calls in the same block if timestamp hasn't changed, but with +1 that's impossible.
        // Let me check the actual contracts again: Both have pastBlockTime = block.timestamp + 1.
        // The only difference is > vs >=. With +1, both conditions effectively require next timestamp > previous timestamp + 1 (reference) or next timestamp >= previous timestamp + 1 (bug) - both require next timestamp > previous timestamp.
        // So they are observationally identical.
        // This is a trick: the bug doesn't change observable behavior. In that case I cannot make one pass and one fail.
        // The problem expects I find a scenario where they diverge.
        // Maybe the +1 is to prevent reentrancy in same block? But timestamp changes...
        // Actually let me re-read carefully: pastBlockTime is initialized to 0 (default).
        // First call: require(block.timestamp > 0) - always true if block.timestamp >= 1.
        // After first call: pastBlockTime = block.timestamp + 1.
        // Second call same block: require(block.timestamp > block.timestamp + 1) = false => revert reference.
        // Bug: require(block.timestamp >= block.timestamp + 1) = false => revert too.
        // So both revert on second call in same block. No difference.
        // Scenario: call at time 1, then call at time 2: reference requires 2 > (1+1)=2 => false => revert; bug requires 2 >= 2 => true => success!
        // That's the divergence!

        // Reset state by deploying new contract
        c = new C();
        vm.warp(1);
        vm.roll(15);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool okFirst,) = address(c).call{value: 10 ether}("");
        assertTrue(okFirst);

        // Now warp to timestamp 2
        vm.warp(2);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool okSecond,) = address(c).call{value: 10 ether}("");

        // Reference: requires 2 > 2 => false => revert => okSecond = false
        // Bug: requires 2 >= 2 => true => success => okSecond = true
        // So assertion: okSecond should be true (buggy version) but reference is false.
        // Wait, I need the reference to pass and bug to fail. The problem says test PASSES on REFERENCE and FAILS on bug.
        // So I need an assertion that is true for reference but false for bug.
        // In above, reference reverts (okSecond false), bug succeeds (okSecond true).
        // If I assertTrue(okSecond) then reference fails (okSecond false) and bug passes (okSecond true) - opposite.
        // If I assertTrue(!okSecond) then reference passes (!false = true) and bug fails (!true = false).
        // That works!

        assertTrue(!okSecond); // Reference: okSecond false => !okSecond true (pass)
        // Bug: okSecond true => !okSecond false (fail)
    }
}

