pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        uint startTime = 100;
        vm.warp(startTime);
        vm.roll(1);

        vm.deal(address(this), 30 ether);

        // First fallback call
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Second fallback call in same block
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);

        // Third fallback call in same block
        (bool ok3, ) = address(c).call{value: 10 ether}("");

        // The reference requires block.timestamp > pastBlockTime, and after two calls pastBlockTime = startTime + 2 in reference, so block.timestamp (100) is not > 102 -> revert; bug version sets pastBlockTime = startTime, so 100 > 100 is false -> also revert. Wait, let's re-evaluate.
        // Actually reference: first call sets pastBlockTime = startTime + 1 = 101; second call: require(101 > 101) false -> revert. So second call fails. That means on reference version, ok2 is false. But we need reference to pass and bug to fail on the same scenario.
        // Let's adjust: Use two calls with different timestamps to make reference succeed and bug fail.
        // Reset
        c = new C();
        vm.warp(100);
        vm.roll(1);
        // First call at t=100
        (bool okA, ) = address(c).call{value: 10 ether}("");
        assertTrue(okA);
        // Advance time by 2 so that block.timestamp > pastBlockTime holds for reference (pastBlockTime=101 after first call)
        vm.warp(103);
        // Second call: reference requires 103 > 101 -> true; bug requires 103 > 100 -> true. Not divergent.
        // Need to find a concrete scenario that diverges.
        // Let's think: Reference increments pastBlockTime by 1, bug sets to block.timestamp.
        // After two calls without time change on reference, pastBlockTime = start+2, bug sets = start.
        // A third call in same block: reference requires t > start+2 -> false; bug requires t > start -> false, both revert. Not divergent.
        // To get divergence, call at t=100, then t=102, then call at t=101.
        // Reference: first call -> pastBlockTime=101. Second call at 102 -> require(102>101) pass, sets pastBlockTime=103. Third call at 101 (warp back) -> require(101>103) false -> revert.
        // Bug: first call -> pastBlockTime=100. Second call at 102 -> require(102>100) pass, sets pastBlockTime=102. Third call at 101 -> require(101>102) false -> revert. Both revert.
        // Need scenario where reference passes and bug reverts, or vice versa.
        // Consider: reference increments, so after first call, pastBlockTime = t+1. Second call at same t fails (require(t > t+1) false). Bug at same t: require(t > t) false, also fails. No divergence.
        // Consider: first call at t=100, second at t=102: reference sets pastBlockTime=101 then pastBlockTime=103. Third call at t=103: require(103>103) false -> revert. Bug: sets to 100 then 102; third call at 103: require(103>102) pass, sets to 103. So reference reverts, bug passes. That works!
        // Let's implement that.
        c = new C();
        vm.warp(100);
        vm.roll(1);

        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        vm.warp(102);
        vm.roll(1);

        (bool ok3, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok3);

        vm.warp(103);

        (bool ok4, ) = address(c).call{value: 10 ether}("");
        // Reference: require(103 > pastBlockTime (which is 103 after previous call) ) -> false, reverts. Bug: require(103 > 102) true, passes.
        assertTrue(ok4); // On reference this should be false, on bug true. But we need assertion that reference holds and bug breaks. So we assert that the call succeeds (bug passes) but reference fails. However our test is on the reference, so we need to write assertion that is true for reference. For reference, ok4 is false. So we assertTrue(!ok4)? But bug gives !ok4 = false. Let's invert: assertTrue(ok4 == false). For reference: ok4 == false -> true; for bug: false -> false. That's the required pattern.
        assertTrue(ok4 == false);
    }
}

