        vm.warp(101);
        vm.deal(alice, sentValue);
        vm.prank(alice);
        (bool ok2, ) = address(c).call{value: sentValue}("");

        // In the reference version: first call succeeds, second reverts because timestamp not > pastBlockTime (100 > 101? false), third succeeds after second failed
        // Actually second call reverts, so ok1 = false, third call succeeds (timestamp 101 > 101? no, because pastBlockTime was set to 101 after first call)
        // Wait, need correct sequence:
        // First call: timestamp 100, pastBlockTime 0 -> passes, sets pastBlockTime = 101
        // Second call at timestamp 100: requires 100 > 101 false -> reverts -> ok1 = false
        // Third call at timestamp 101: requires 101 > 101 false -> reverts in reference -> ok2 = false
        // In modified: first call sets pastBlockTime = 100, second call at 100 requires 100 > 100 false -> still reverts; third call at 101 requires 101 > 100 true -> passes
        // So divergence: in reference, third call reverts (ok2 = false), in modified, third call passes (ok2 = true)
        // We assert that ok2 is false (reference property) which fails on modified

        assertTrue(!ok2);
