pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block number to 1 so first fallback won't trigger the if (block.number % 15 != 0)
        vm.roll(1);
        vm.warp(1000);
        vm.deal(address(0x1), 10 ether);
        vm.prank(address(0x1));
        c.fallback{value: 10 ether}();

        // Now set block number to 15 (divisible by 15) and same timestamp, so the second call triggers the if
        vm.roll(15);
        vm.warp(1000);
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: require(block.timestamp > pastBlockTime) passes because pastBlockTime = 1001, 1000 > 1001 is false? Wait 1000 > 1001 false — I must correct.
        // Correction: In reference, pastBlockTime becomes 1001. At same timestamp 1000, require(1000 > 1001) fails in reference? No, then reference would also revert. I need a scenario where reference succeeds and bug fails.
        // Rethink: Let first call at t=1000, reference sets pastBlockTime=1001. Second call at t=1002 (later timestamp) but at block number 15, reference: require(1002 > 1001) true, bug: require(1002 > 1000) true — both pass. Must diverge.
        // Proper divergence: first call at t=1000, reference sets pastBlockTime=1001. Second call at t=1001, block 15. Reference: require(1001 > 1001) false (fails), bug: require(1001 > 1000) true (passes). Actually bug passes, reference fails — opposite of requirement.
        // I need reference passes, bug fails. So: first call at t=1000, reference sets pastBlockTime=1001. Second call at t=1001, block 15. Reference fails, but test should pass on reference? No, test must pass on reference, so reference must not revert. So we need scenario where reference passes and bug fails.
        // Corrected: first call at t=1000, reference sets pastBlockTime=1001. Second call at t=1002 (t > 1001), block 15. Reference passes, bug: sets pastBlockTime=1000, require(1002 > 1000) passes too — both pass. No divergence.
        // Key: Reference updates to block.timestamp + 1, bug updates to block.timestamp. Divergence occurs when second call at same timestamp as first? No, then reference fails because require(1000 > 1001) false, bug passes because require(1000 > 1000) false? Actually 1000 > 1000 false, so both fail.
        // To get reference passes and bug fails: first call at t=0, reference sets pastBlockTime=1. Second call at t=1, block 15. Reference: require(1 > 1) false (fails). Bug: require(1 > 0) true (passes). Still opposite.
        // Let me re-express: Reference increments by 1, bug doesn't. So after first call at time T, reference has pastBlockTime = T+1, bug has T. If second call at time T (same timestamp): reference revert (T > T+1 false), bug revert (T > T false) — both revert. If second call at time T+1: reference require(T+1 > T+1) false → revert, bug require(T+1 > T) true → pass. So reference fails, bug passes.
        // For reference passes, bug fails: need second call at T+2: reference require(T+2 > T+1) true, bug require(T+2 > T) true → both pass. No.
        // Wait, mistake: reference sets pastBlockTime = block.timestamp + 1. So if first call at 0, reference pastBlockTime=1. Second call at 1: reference require(1>1) false, bug require(1>0) true. So bug passes, reference fails. That's the reverse.
        // The problem asks for test that passes on reference and fails on bug. So must find case where reference passes, bug fails. For that we need reference condition true, bug condition false. Reference requires block.timestamp > pastBlockTime, bug same. If pastBlockTime is larger in reference, then reference is harder to satisfy. So reference passes where bug fails would require reference's pastBlockTime smaller than bug's? But reference adds 1, so pastBlockTime larger. Thus reference always has larger or equal (since timestamp same or larger) => reference condition is stricter. So reference can never pass where bug fails. The only divergence is bug passes and reference fails. So test must reverse: test passes on bug? No, test must pass on reference.
        // Therefore the only observable divergence from a single added 1 is that reference may revert where bug doesn't. But the rule says test must pass on reference and fail on bug. That would require bug to revert where reference doesn't, which is impossible with this change. However maybe the divergence is in state: after second call, pastBlockTime differs. We can read it.
        // Yes! We can read pastBlockTime via getter. So use that.
        // Scenario: first call at block not %15, then second call at block %15 triggers transfer which empties balance. But we can also check pastBlockTime after second call regardless of revert.
        // To avoid revert, choose timestamps so both calls succeed: first call at t=0, second call at t=2 (t > 1 for reference, t > 0 for bug). Both succeed. Then read pastBlockTime: reference has 1, bug has 2? Wait: reference sets pastBlockTime = block.timestamp + 1 = 0+1 = 1 after first call. Second call at t=2: reference sets pastBlockTime = 2+1 = 3; bug sets = 2. So after second call, reference pastBlockTime=3, bug=2. So we can assert that pastBlockTime == 3 for reference, and for bug it's 2, so assertEq(c.pastBlockTime(), 3) passes on reference, fails on bug.
        // Perfect, and no reverts.
        // Set up: first call at block not %15.
        vm.roll(1);
        vm.warp(0);
        vm.deal(address(0x1), 10 ether);
        vm.prank(address(0x1));
        c.fallback{value: 10 ether}();

        // second call at block %15, later timestamp
        vm.roll(15);
        vm.warp(2);
        vm.deal(address(0x2), 10 ether);
        vm.prank(address(0x2));
        // The transfer will deplete balance but that's fine
        c.fallback{value: 10 ether}();

        // Now read pastBlockTime
        uint storedTime = c.pastBlockTime();
        // Reference: after second call, pastBlockTime = block.timestamp + 1 = 2 + 1 = 3
        // Bug: after second call, pastBlockTime = block.timestamp = 2
        assertEq(storedTime, 3);
    }
}

