        (bool ok2,) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");
        // Now contract balance = 20, pastBlockTime=4
        vm.roll(15);
        vm.warp(5);
        // Third call: try/catch to capture revert
        bool callSucceeded;
        try address(c).call{value: 10 ether}("") {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }
        // In reference, call reverts (transfer fails), so callSucceeded = false; pastBlockTime unchanged (4). In buggy, call succeeds (send fails but call continues), callSucceeded = true; pastBlockTime becomes 6.
        // Assert that the call reverted (reference) or succeeded (buggy). Actually we need reference to pass and buggy to fail. Let's assert that callSucceeded == false. That passes reference (call reverts) and fails buggy (call succeeds). But wait: in buggy, send fails but call proceeds, so callSucceeded = true. So assertTrue(!callSucceeded) would fail for buggy.
        assertTrue(!callSucceeded);
    }
}

