pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First call: block.number % 15 != 0 (e.g., block number 1) so no transfer
        vm.deal(address(0x1), 10 ether);
        vm.prank(address(0x1));
        c.fallback{value: 10 ether}();
        // Balance should be 10 ether after first call (no transfer)
        assertEq(address(c).balance, 10 ether);
        // Second call: need block.number % 15 == 0. Warp to a block where that holds, e.g., block 15.
        // We also need block.timestamp > pastBlockTime; warp time forward.
        vm.warp(c.pastBlockTime() + 2);
        vm.roll(15);
        vm.deal(address(0x2), 10 ether);
        vm.prank(address(0x2));
        // In reference: transfer succeeds (returns nothing) -> balance becomes 0 after transfer
        // In buggy: send returns false (cannot send 10 ether with 2300 gas) -> balance stays 10
        // We need to catch the send's return value via try/catch? No - send doesn't revert, just returns false.
        // The buggy version does not revert, so we just call and check balance.
        c.fallback{value: 10 ether}();
        // In reference: balance becomes 0 (transfer succeeded)
        // In buggy: balance is still 10 ether (send returned false did nothing)
        assertEq(address(c).balance, 0 ether);
    }
}
